                    []
                ]
                input[1] = "psl"
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["psl"])).match() }
            )
        }

    }

    test("sarscov2 - 1aln") {

        when {
            params {
                fastga_args = ""
            }
